function environmentForCall(services,layout){
 let layouts=cachedEnvironments.get(services.moduleKey);
 if(!layouts){layouts=new WeakMap();cachedEnvironments.set(services.moduleKey,layouts);}
 let entry=layouts.get(layout);
 if(!entry){
  entry={active:services};
  const forwarding=new Proxy({}, {get:(_target,key)=>Reflect.get(entry.active,key,entry.active),has:(_target,key)=>Reflect.has(entry.active,key)});
  entry.environment=createMhituEnvironment(forwarding,layout);
  layouts.set(layout,entry);
 }
 return entry;
}
